import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';

test('createInvoice creates a draft invoice with enriched lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
  assert.equal(r.value.issueDate, '2026-10-07');
  assert.equal(r.value.status, 'draft');
  assert.equal(r.value.lines.length, 1);
  assert.equal(r.value.lines[0].sku, 'DES-HOUR');
  assert.equal(r.value.lines[0].name, 'Design work (hour)');
  assert.equal(r.value.lines[0].qty, 10);
  assert.equal(r.value.lines[0].unitPrice, 8500);
  assert.equal(r.value.lines[0].vatRate, 21);
});

test('createInvoice handles multiple lines', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
      { sku: 'PRINT-A4', qty: 100 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 3);
  assert.equal(r.value.lines[0].name, 'Development (hour)');
  assert.equal(r.value.lines[1].name, 'Logo package');
  assert.equal(r.value.lines[2].name, 'Printed flyer A4 (each)');
});

test('createInvoice reports CUSTOMER_NOT_FOUND', () => {
  const r = createInvoice({
    customerId: 'C-999',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice reports DATE_INVALID for wrong format', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '07-10-2026',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026/10/07',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice reports DATE_INVALID for impossible dates', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-02-30',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-13-01',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice reports NO_LINES for empty lines array', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [],
    }),
    { ok: false, error: 'NO_LINES' }
  );
});

test('createInvoice reports NO_LINES for missing lines', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: undefined,
    }),
    { ok: false, error: 'NO_LINES' }
  );
});

test('createInvoice reports QTY_INVALID for non-integer qty', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1.5 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: '5' }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice reports QTY_INVALID for zero or negative qty', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 0 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: -5 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice reports UNKNOWN_SKU', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'UNKNOWN-SKU', qty: 1 }],
    }),
    { ok: false, error: 'UNKNOWN_SKU' }
  );
});

test('createInvoice does not mutate arguments', () => {
  const lines = [{ sku: 'DES-HOUR', qty: 10 }];
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines,
  });
  assert.deepEqual(lines, [{ sku: 'DES-HOUR', qty: 10 }]);
  result.value.lines[0].qty = 999;
  assert.deepEqual(lines, [{ sku: 'DES-HOUR', qty: 10 }]);
});

test('lineTotal calculates qty times unitPrice', () => {
  assert.equal(lineTotal({ qty: 10, unitPrice: 8500 }), 85000);
  assert.equal(lineTotal({ qty: 1, unitPrice: 120000 }), 120000);
  assert.equal(lineTotal({ qty: 100, unitPrice: 37 }), 3700);
});

test('invoiceTotals returns subtotal and total', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 8500 },
      { qty: 1, unitPrice: 120000 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 205000);
  assert.equal(totals.total, 205000);
});

test('invoiceTotals works with single line', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 6000 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 30000);
  assert.equal(totals.total, 30000);
});

test('invoiceTotals works with many lines', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 8500 },
      { qty: 5, unitPrice: 9500 },
      { qty: 1, unitPrice: 120000 },
      { qty: 100, unitPrice: 37 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 85000 + 47500 + 120000 + 3700);
  assert.equal(totals.total, 256200);
});

test('invoiceTotals does not mutate invoice', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 8500 }],
  };
  const originalJSON = JSON.stringify(invoice);
  invoiceTotals(invoice);
  assert.equal(JSON.stringify(invoice), originalJSON);
});

test('addLine adds a new line to an invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const invoice = r1.value;

  const r2 = addLine(invoice, { sku: 'DEV-HOUR', qty: 5 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 2);
  assert.equal(r2.value.lines[0].sku, 'DES-HOUR');
  assert.equal(r2.value.lines[0].qty, 10);
  assert.equal(r2.value.lines[1].sku, 'DEV-HOUR');
  assert.equal(r2.value.lines[1].qty, 5);
  assert.equal(r2.value.lines[1].name, 'Development (hour)');
});

test('addLine increases qty if SKU already exists', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const invoice = r1.value;

  const r2 = addLine(invoice, { sku: 'DES-HOUR', qty: 5 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 1);
  assert.equal(r2.value.lines[0].sku, 'DES-HOUR');
  assert.equal(r2.value.lines[0].qty, 15);
});

test('addLine reports QTY_INVALID', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const invoice = r1.value;

  assert.deepEqual(addLine(invoice, { sku: 'DEV-HOUR', qty: 0 }), {
    ok: false,
    error: 'QTY_INVALID',
  });
  assert.deepEqual(addLine(invoice, { sku: 'DEV-HOUR', qty: -5 }), {
    ok: false,
    error: 'QTY_INVALID',
  });
  assert.deepEqual(addLine(invoice, { sku: 'DEV-HOUR', qty: 1.5 }), {
    ok: false,
    error: 'QTY_INVALID',
  });
});

test('addLine reports UNKNOWN_SKU', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const invoice = r1.value;

  assert.deepEqual(addLine(invoice, { sku: 'NOPE', qty: 1 }), {
    ok: false,
    error: 'UNKNOWN_SKU',
  });
});

test('addLine reports NOT_DRAFT for non-draft invoices', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const invoice = { ...r1.value, status: 'sent' };

  assert.deepEqual(addLine(invoice, { sku: 'DEV-HOUR', qty: 1 }), {
    ok: false,
    error: 'NOT_DRAFT',
  });
});

test('addLine does not mutate the original invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const invoice = r1.value;
  const originalJSON = JSON.stringify(invoice);

  addLine(invoice, { sku: 'DEV-HOUR', qty: 5 });
  assert.equal(JSON.stringify(invoice), originalJSON);
});

test('removeLine removes a line from an invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'DEV-HOUR', qty: 5 },
    ],
  });
  const invoice = r1.value;

  const r2 = removeLine(invoice, 'DES-HOUR');
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 1);
  assert.equal(r2.value.lines[0].sku, 'DEV-HOUR');
});

test('removeLine reports LINE_NOT_FOUND', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const invoice = r1.value;

  assert.deepEqual(removeLine(invoice, 'NOPE'), {
    ok: false,
    error: 'LINE_NOT_FOUND',
  });
});

test('removeLine reports NO_LINES when removing the last line', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const invoice = r1.value;

  assert.deepEqual(removeLine(invoice, 'DES-HOUR'), {
    ok: false,
    error: 'NO_LINES',
  });
});

test('removeLine reports NOT_DRAFT for non-draft invoices', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'DEV-HOUR', qty: 5 },
    ],
  });
  const invoice = { ...r1.value, status: 'sent' };

  assert.deepEqual(removeLine(invoice, 'DES-HOUR'), {
    ok: false,
    error: 'NOT_DRAFT',
  });
});

test('removeLine does not mutate the original invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'DEV-HOUR', qty: 5 },
    ],
  });
  const invoice = r1.value;
  const originalJSON = JSON.stringify(invoice);

  removeLine(invoice, 'DES-HOUR');
  assert.equal(JSON.stringify(invoice), originalJSON);
});
